python3 - <<'EOF'
import re, glob
# crude: find methods by brace tracking, report longest in jadx-core main
results=[]
for path in glob.glob('jadx-core/src/main/java/**/*.java', recursive=True):
    with open(path) as f: lines=f.readlines()
    i=0; n=len(lines)
    sig=re.compile(r'^\s+(public|private|protected)\s.*\)\s*(throws [\w, ]+)?\s*\{\s*$')
    for idx,l in enumerate(lines):
        if sig.match(l) and 'class ' not in l and 'interface ' not in l:
            # count braces until balanced
            depth=0; start=idx; end=None
            for j in range(idx,n):
                depth+=lines[j].count('{')-lines[j].count('}')
                if depth<=0 and j>idx:
                    end=j; break
            if end:
                length=end-start
                if length>=100:
                    name=l.strip()[:70]
                    results.append((length,path,start+1,name))
results.sort(reverse=True)
for r in results[:15]:
    print(f"{r[0]:4d} lines  {r[1]}:{r[2]}  {r[3]}")
EOF

